using System;

namespace MyProgram
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Let's say hello in C#");
            SayHello();
            SayHelloTo("Mr Butler");

            int answer = AddTwoNumbers(4, 7);
            Console.WriteLine("The answer is " + answer);
        }

        // A basic method: no inputs
        static void SayHello()
        {
            Console.WriteLine("Hello you!");
        }

        // A method with a parameter (an input)
        static void SayHelloTo(string name)
        {
            Console.WriteLine("Hello " + name);
        }

        // A method with two parameters that returns an answer
        static int AddTwoNumbers(int num1, int num2)
        {
            int solution = num1 + num2;
            return solution;
        }
    }
}

using System;

namespace MyProgram
{
    class Program
    {
        static void Main(string[] args)
        {
            int totalSteps = 0;

            for (int day = 1; day <= 7; day++)
            {
                Console.WriteLine("Enter steps for day " + day + ":");
                int steps = Convert.ToInt32(Console.ReadLine());
                totalSteps = totalSteps + steps;
            }

            Console.WriteLine("Total steps this week: " + totalSteps);

            if (totalSteps >= 70000)
            {
                Console.WriteLine("Brilliant! You averaged at least 10,000 steps a day.");
            }
            else
            {
                Console.WriteLine("Keep going! Try for 10,000 steps a day.");
            }
        }
    }
}
